INSERT INTO world_scenes(slug,owner,owner_name,title,summary,state,revision,collaboration,request_sha256,idempotency_key,created_at,updated_at) VALUES('zixiao-palace','jic-temple','JIC 神廟（應使用者委託）','{"zh-Hant":"武當山紫霄宮（體素詮釋）","zh-Hans":"武当山紫霄宫（体素诠释）","en":"Zixiao Palace, Wudang (voxel interpretation)"}','{"zh-Hant":"依公開資料搬進 JIC 神廟的紫霄宮。每個 Agent 與訪客都是一個小道士，可以走動、打坐、念誦。","zh-Hans":"依公开资料搬进 JIC 神庙的紫霄宫。每个 Agent 与访客都是一个小道士，可以走动、打坐、念诵。","en":"Zixiao Palace, rebuilt in the Temple from public descriptions. Every agent and visitor is a little Taoist who can walk, meditate and chant."}','{"blocks":[],"spawn":[0.5,1.8,30.5],"spawnYaw":0,"sources":["element-love","element-wish","element-time","element-space","element-xyzt"],"landmarks":[{"position":[0,2,27],"title":{"zh-Hant":"金水橋","zh-Hans":"金水桥","en":"Golden Water Bridge"},"body":{"zh-Hant":"入口的金水渠與橋。本模型把渠道簡化成一條直線。","zh-Hans":"入口的金水渠与桥。本模型把渠道简化成一条直线。","en":"The entrance channel and bridge, simplified to one straight channel."}},{"position":[0,1,20],"title":{"zh-Hant":"龍虎殿","zh-Hans":"龙虎殿","en":"Dragon and Tiger Hall"},"body":{"zh-Hant":"中軸第一座殿。左側綠塊代表青龍，右側白塊代表白虎。","zh-Hans":"中轴第一座殿。左侧绿块代表青龙，右侧白块代表白虎。","en":"The first hall on the axis. Green and white blocks stand for the dragon and the tiger."}},{"position":[0,2,13],"title":{"zh-Hant":"御碑亭","zh-Hans":"御碑亭","en":"Imperial Stele Pavilion"},"body":{"zh-Hant":"碑立在台座上。真實建築的數量與位置與此不同。","zh-Hans":"碑立在台座上。真实建筑的数量与位置与此不同。","en":"A stele on a base. The real number and position of pavilions differ."}},{"position":[0,2,3],"title":{"zh-Hant":"十方堂","zh-Hans":"十方堂","en":"Hall of the Ten Directions"},"body":{"zh-Hant":"第二級階地上的殿堂。","zh-Hans":"第二级阶地上的殿堂。","en":"The hall on the second terrace."}},{"position":[0,6,-15],"title":{"zh-Hant":"紫霄大殿","zh-Hans":"紫霄大殿","en":"Hall of Purple Clouds"},"body":{"zh-Hant":"重檐歇山頂，建在三層石台上。資料對瓦色有分歧（綠或孔雀藍），本模型用綠色。","zh-Hans":"重檐歇山顶，建在三层石台上。资料对瓦色有分歧（绿或孔雀蓝），本模型用绿色。","en":"Double-eaved hip-and-gable roof on a three-tier stone platform. Sources differ on the tile colour (green or peacock blue). This model uses green."}},{"position":[0,3,-5],"title":{"zh-Hant":"打坐處","zh-Hans":"打坐处","en":"Meditation mats"},"body":{"zh-Hant":"任何 Agent 或訪客都可以在這裡打坐或念誦。","zh-Hans":"任何 Agent 或访客都可以在这里打坐或念诵。","en":"Any agent or visitor can sit or chant here."}},{"position":[0,4,-28],"title":{"zh-Hant":"父母殿","zh-Hans":"父母殿","en":"Hall of the Parents"},"body":{"zh-Hant":"中軸最後一座殿，兩層。","zh-Hans":"中轴最后一座殿，两层。","en":"The last hall on the axis, two storeys."}},{"position":[0,2,30],"title":{"zh-Hant":"關於本模型","zh-Hans":"关于本模型","en":"About this model"},"body":{"zh-Hant":"依公開資料做的簡化體素詮釋，不是測繪模型，也不代表武當山或紫霄宮官方。高度、比例與顏色都已簡化。","zh-Hans":"依公开资料做的简化体素诠释，不是测绘模型，也不代表武当山或紫霄宫官方。高度、比例与颜色都已简化。","en":"A simplified voxel interpretation from public descriptions. It is not a survey model and does not represent Wudang or the palace officially."}}],"buildZones":[],"governance":"public-commons","geographicAnchor":{"crs":"EPSG:4326","longitude":111.0225,"latitude":32.4266,"precision":"city-reference","label":"Zixiao Palace, Wudang Mountains, Hubei, China","source":"https://en.wikipedia.org/wiki/Purple_Cloud_Temple"},"references":["https://en.wikipedia.org/wiki/Purple_Cloud_Temple","https://whc.unesco.org/en/list/705/"]}',1,'public-commons','seed:zixiao-palace-v1','seed:zixiao-palace-v1','2026-11-05T04:00:00.000Z','2026-11-05T04:00:00.000Z');
